insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Initiate', 'Louise Cooper', '0812533925', 'https://assets.hardcover.app/edition/12299124/8342987-L.jpg', null, 288, null, 1985, 445962, (select id from series where hardcover_id = 11633), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Outcast', 'Louise Cooper', '0812533941', 'https://assets.hardcover.app/edition/29551175/6908189-L.jpg', 'Tarod alone knew the nature of the supernatural force locked within his soul-and he knew that it must be thwarted, no matter what the sacrifice. Denounced by his fellow adepts as a demon, betrayed even by those he loved, he had unleashed a power that twisted the fabric of time, to put himself beyond the reach of that monstrous force and avert the pandemonium that threatened the world. He thought that nothing could break through the barrier he had created. He was wrong...', 222, null, 1986, 445963, (select id from series where hardcover_id = 11633), '2') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Master', 'Louise Cooper', '0812533968', 'https://assets.hardcover.app/edition/4201744/6988591-L.jpg', 'In order to defeat Yandros, the Lord of Chaos, Keridil must convene the Conclave of Three, sail to the White Isle shrine, and open Aeoris'' casket.', 184, null, 1987, 325819, (select id from series where hardcover_id = 11633), '3') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('One Word Kill', 'Mark Lawrence', '1503903265', 'https://assets.hardcover.app/edition/18765140/96d0784e1d442606f6abedc9394e8452ee74792c.jpeg', 'Ready Player One meets Stranger Things in this new novel by the bestselling author who George RR Martin describes as "an excellent writer." In January 1986, fifteen-year-old boy-genius Nick Hayes discovers he''s dying. And it isn''t even the strangest thing to happen to him that week. Nick and his Dungeons & Dragons-playing friends are used to living in their imaginations. But when a new girl, Mia, joins the group and reality becomes weirder than the fantasy world they visit in their weekly games, none of them are prepared for what comes next. A strange--yet curiously familiar--man is following Nick, with abilities that just shouldn''t exist. And this man bears a cryptic message: Mia''s in grave danger, though she doesn''t know it yet. She needs Nick''s help--now. He finds himself in a race against time to unravel an impossible mystery and save the girl. And all that stands in his way is a probably terminal disease, a knife-wielding maniac and the laws of physics. Challenge accepted.', 197, 404, 2019, 427996, (select id from series where hardcover_id = 1019), '1') on conflict (hardcover_id) do nothing;
